import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"工件台加速度与产能","description":"","frontmatter":{"title":"工件台加速度与产能","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/stage-acceleration-throughput.md","filePath":"litho/stage-acceleration-throughput.md","lastUpdated":1789023840000}'),p={name:"litho/stage-acceleration-throughput.md"};function u(_,a,E,A,m,B){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="工件台加速度与产能" tabindex="-1">工件台加速度与产能 <a class="header-anchor" href="#工件台加速度与产能" aria-label="Permalink to &quot;工件台加速度与产能&quot;">​</a></h1><div class="epigraph"><p>扫描产能不是激光有多亮，常是台能加多快、转向多重而不把套刻抖坏。加速度进会计，也进伺服残差。</p><footer>—— 对照 [扫描仪产能](/litho/scanner-throughput)；双工件台见 [Twinscan](/litho/twinscan-dual-stage)</footer></div><p><a href="/litho/vibration-isolation">上一课</a>挡住地。缺口是台自己：扫描段匀速，场间加速、转向、对准。本课钉加速度与产能，同步误差下一课 MSD。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吞吐公式里有加速时间。加速度大，死时间短，但力大、液膜难、隔振被打。只升激光 \\(f\\)，台加不上速，产能不动。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运动规划：扫描速度、加速极限、急动度 jerk 限制。双台：一块曝光一块对准，掩盖加速。浸没头对加速度有流体上限。会计：把加速段从「曝光时间」里分开报，否则优化激光会失望。</p>',7)),(e(),s(c,null,{default:o(()=>[d(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8A%A0%E9%80%9F%E5%BA%A6%E4%B8%8A%E9%99%90%22%5D%20--%3E%20T%5B%22%E5%9C%BA%E9%97%B4%E6%AD%BB%E6%97%B6%E9%97%B4%22%5D%0A%20%20T%20--%3E%20WPH%5B%22%E7%89%87%2F%E5%B0%8F%E6%97%B6%22%5D%0A%20%20A%20--%3E%20F%5B%22%E5%8A%9B%20%2F%20%E6%B6%B2%E8%86%9C%22%5D%0A%20%20F%20--%3E%20OVL%5B%22%E5%A5%97%E5%88%BB%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>牛顿定律：力 = 质量 × 加速度。台+片+夹盘质量固定，加速度直接是对导轨与隔振的力。液膜在转向时剪切，缺陷与同步误差一起升。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课 MSD：加速度规划得再漂亮，扫描中掩模台与工件台跟不齐仍糊。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产能会计必须单列加速死时间。</li><li>加速度与套刻、浸没流体抢同一条力预算。</li><li>出处：扫描仪产能课；Twinscan。</li></ul>',6))])}const b=i(p,[["render",u]]);export{T as __pageData,b as default};
